// v23.xx (gfx10), HIS ORDER (2026-10-12) on the graphics program, item 2, shadows that follow light: FLASH SHADOWS. Under
// LIGHTING HIGH gunfire and blasts are cut by the walls the way the lamps are (gfx8): a frag going off behind a wall lights the
// ground on its own side, not the floor you stand on beyond the wall. Each flash casts its sight polygon once, on the first frame
// it is drawn (the same lift-aware cast as a lamp cookie), keeps it for the rest of its short life in a WeakMap keyed by the flash
// itself (nothing is written on the flash), and its light and its bloom are drawn through it, 15 percent left outside as bounce.
// At most 4 new flashes are cast a frame; past that a flash draws unshadowed for that frame. STANDARD and CLASSIC are unchanged.
var FPOLY=(typeof WeakMap==='function')?new WeakMap():null, FPOLYN={made:0,frame:0};
function gfxFlashPoly(F,mk){
  var segs=G&&G.map&&G.map.segs, e;
  if(!FPOLY||!F||!segs) return null;
  e=FPOLY.get(F);
  if(e&&e.segs===segs) return e.poly;
  if(!mk||!(FPOLYN.frame>0)) return null;
  FPOLYN.frame--; FPOLYN.made++;
  e={segs:segs,poly:gfxLampPoly({x:F.x,y:F.y,r:Math.max(1,F.r)})};
  FPOLY.set(F,e);
  return e.poly;
}
function gfxClipPoly(c,poly){
  var i;
  c.beginPath(); c.moveTo(poly[0],poly[1]);
  for(i=2;i<poly.length;i+=2) c.lineTo(poly[i],poly[i+1]);
  c.closePath(); c.clip();
}
function gfxLightFail(e){

var hi=(((typeof gfxLightNow==='function')?gfxLightNow():CFG.gfxLight)!==1), ck, fp;   // v23.xx (gfx8): HIGH casts the lamps through their cookies; STANDARD (and the quality ladder's rung 3) draws the plain pools
LCOOK.budget=hi?2:0;
FPOLYN.frame=hi?4:0;   // v23.xx (gfx10): new flash shadows cast this frame

fp=hi?gfxFlashPoly(F,true):null;   // v23.xx (gfx10): the flash through its own shadow polygon, 15 percent bounce outside it
if(fp){
  put(gfxLightSpr(F.c||'#ffc27a','map'),F.x,F.y,frr,2*a*.9*fr*.15);
  x.save(); gfxClipPoly(x,fp); put(gfxLightSpr(F.c||'#ffc27a','map'),F.x,F.y,frr,2*a*.9*fr*.85); x.restore();
} else put(gfxLightSpr(F.c||'#ffc27a','map'),F.x,F.y,frr,2*a*.9*fr);

fp=hi?gfxFlashPoly(F2,false):null;   // v23.xx (gfx10): the bloom stays on the flash's own side of the walls
if(fp){ wc.save(); gfxClipPoly(wc,fp); }
wc.globalAlpha=.30*f2; wc.fillStyle=F2.c||'#ffc27a';
wc.beginPath(); wc.arc(gx,gy,gr2,0,6.2832); wc.fill();
if(fp) wc.restore();

