{v:'VER',what:'graphics program gfx10: flash shadows: under LIGHTING HIGH a blast flash north of a wall gives the floor south of the wall at most a quarter of the light it gives open floor the same distance north, its shadow polygon is cast once on its first frame and not again on the next, and STANDARD still lights both alike',
 run:function(){
   if(!(window.__gfxStage&&window.__frame&&window.__state&&window.__endRaid)||typeof render2D!=='function') return 'SKIP: this fixture cannot stage and draw a raid frame';
   if(typeof FPOLY==='undefined'||typeof gfxFlashPoly!=='function'||typeof LMAP==='undefined'||typeof gfxLampPoly!=='function') return 'no flash shadows: no FPOLY';
   var bad=[], g=null, p, gl0=CFG.gfxLight, L0=null, E0=null, F0=null, W=null, ws, i, k, w, cx, Fy, Qy, Oy, amb, keepLP=gfxLampPoly, nLP=0, fl, base, lit, sQ, sO, hQ, hO, n1, n2;
   function inWall(x,y,skip){ for(var q=0;q<ws.length;q++){ var v=ws[q]; if(v===skip) continue; if(x>=v.x-3&&x<=v.x+v.w+3&&y>=v.y-3&&y<=v.y+v.h+3) return true; } return false; }
   function mapAt(wx,wy){
     var Zq=ZOOM()*SOFTR, mx=Math.round((wx-VX)*Zq), my=Math.round((wy-VY)*Zq), d, m, s=0, n=0;
     if(mx<2||my<2||mx>LMAP.c.width-3||my>LMAP.c.height-3) return null;
     d=LMAP.x.getImageData(mx-1,my-1,3,3).data;
     for(m=0;m<d.length;m+=4){ s+=d[m+1]; n++; }
     return s/n;
   }
   function frame(q,withF){ CFG.gfxLight=q; G.flashes=withF?[fl]:[]; __frame(0); return [mapAt(cx,Qy),mapAt(cx,Oy)]; }
   try{
     __resetCfg();
     g=__gfxStage({cond:'night',wx:'clear',frames:3});
     if(!g) return 'SKIP: __gfxStage built no raid';
     if(isDay()) return 'SKIP: the staged raid is not at night';
     p=g.player; G.shake=0; G.lightning=0; ws=G.map.walls;
