       w=ws[i];
       if(w.tree||w.furn||w.wreck||w.ruin||w.win||w.door||w.ledge||w.lockWall||w.w<80||w.h>40) continue;
       cx=w.x+w.w/2; Fy=w.y-45; Qy=w.y+w.h+45; Oy=Fy-(Qy-Fy);
       if(Oy<60||Qy>WORLD_H-60||cx<300||cx>WORLD_W-300) continue;
       if(inWall(cx,Fy,null)||inWall(cx,Qy,null)||inWall(cx,Oy,null)) continue;
       var clear=true; for(k=Oy;k<=Qy;k+=4){ if(k>=w.y-3&&k<=w.y+w.h+3) continue; if(inWall(cx,k,w)){ clear=false; break; } }
       if(!clear) continue;
       W=w;
     }
     if(!W) return 'SKIP: staging: no plain wall with open floor both sides';
     L0=G.lights; E0=G.ents; F0=G.flashes; G.ents=[]; G.lights=[];
     p.x=cx+260; p.y=Fy; G.anchX=undefined;
     G.flashes=[]; for(k=0;k<4;k++) __frame(0.12);
     fl={x:cx,y:Fy,r:200,c:'#ffffff',t:0,life:.25};
     base=frame(1,false); lit=frame(1,true);
     if(base[0]===null||base[1]===null||lit[0]===null||lit[1]===null) return 'SKIP: staging: the wall left the screen';
     sQ=lit[0]-base[0]; sO=lit[1]-base[1];
     if(!(sO>=6)) return 'SKIP: staging: the flash gives open floor only '+sO;
     if(Math.abs(sQ-sO)>Math.max(3,sO*.25)) bad.push('under STANDARD the flash lights the two sides unlike: '+sQ.toFixed(1)+' against '+sO.toFixed(1));
     gfxLampPoly=function(Lq){ nLP++; return keepLP(Lq); };
     fl={x:cx,y:Fy,r:200,c:'#ffffff',t:0,life:.25};
     base=frame(2,false); nLP=0; lit=frame(2,true); n1=nLP; nLP=0;
     hQ=lit[0]-base[0]; hO=lit[1]-base[1];
     G.flashes=[fl]; __frame(0); n2=nLP;
     gfxLampPoly=keepLP;
     if(!(hO>=6)) bad.push('under HIGH the flash lights open floor only '+hO.toFixed(1));
     else if(hQ>0.25*hO) bad.push('under HIGH the floor south of the wall gets '+hQ.toFixed(1)+' of the flash light against '+hO.toFixed(1)+' on open floor (want a quarter or less)');
     if(n1!==1) bad.push('the flash shadow was cast '+n1+' times on its first frame (want 1)');
     if(n2!==0) bad.push('the flash shadow was cast again '+n2+' times on its second frame (want 0)');
   }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
   finally{
     gfxLampPoly=keepLP; CFG.gfxLight=gl0;
     try{ if(g&&G===g){ if(L0) G.lights=L0; if(E0) G.ents=E0; G.flashes=F0||[]; } }catch(_r){}
     try{ var g2=__state(); if(g2&&!g2.over) __endRaid('abandon'); }catch(_e){}
     __topClear(); __cleanProfile();
   }
   return bad.length?bad.join('; '):null; }},
